import sys
data = sys.stdin.read().split()
if data:
    n, target = int(data[0]), int(data[1])
    nums = [int(x) for x in data[2:2+n]]
    lookup = {}
    found = False
    for i, num in enumerate(nums):
        comp = target - num
        if comp in lookup:
            print(f'{lookup[comp]} {i}')
            found = True
            break
        lookup[num] = i
    if not found: print('-1 -1')
